import { sql } from 'drizzle-orm';
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

// Column helpers shared by every table, so the conventions decided in Phase 0 live in one place.

/**
 * Primary key: a UUIDv7 generated by Postgres 18's built-in uuidv7().
 * The first 48 bits are a millisecond timestamp, so new ids land at the end of the B-tree index
 * (like 1, 2, 3 would) while staying unguessable (unlike 1, 2, 3).
 */
export const primaryId = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

/**
 * timestamptz(3): one exact instant, stored in UTC with millisecond precision
 * (the precision a JavaScript Date has, so values round-trip without loss).
 */
export const timestamptz = (name: string) => timestamp(name, { precision: 3, withTimezone: true });

export const createdAt = () => timestamptz('created_at').notNull().defaultNow();

/**
 * Set by Drizzle whenever the API updates the row (`$onUpdate`).
 * Deliberately not a database trigger: the counter triggers also update rows in `users` and
 * `posts` (follower_count, like_count, ...), and a new like must not change a post's updated_at.
 */
export const updatedAt = () =>
  timestamptz('updated_at')
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** Postgres's full-text search document type. Drizzle has no built-in column type for it. */
export const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' });
